//! Golden-master parity harness for the deterministic economic turn.
//!
//! This integration-test file loads a Python-generated save state, runs the
//! Rust `run_economic_turn` function, and compares the resulting `Treasury` and
//! `MacroData` against the expected "Turn + 1" output generated by the Python
//! engine. For Target 2 Part 1 the only ported formula is the sector-level GDP
//! share update from employment (`economy/indicators/core.py`); the harness
//! proves the Rust math matches the Python logic with hardcoded expected values.

use sim_engine::economy::indicators::{run_economic_turn, update_gdp_shares_from_employment, CountryTurnCtx, ParityResult};
use sim_engine::economy::market::{GlobalMarket, MarketOrders, MarketSignal};
use sim_engine::economy::process_building_cycle;
use sim_engine::economy::process_demographics_and_labor;
use sim_engine::economy::resolve_market_prices;
use sim_engine::entities::{ActiveProductionMethod, Building, Company};
use sim_engine::engine::{run_turn_in_memory, InMemoryTurnContext};
use sim_engine::io::save_manager::{load_game_state, load_country_data};
use sim_engine::registries::enums::Commodity;
use sim_engine::registries::Registries;
use sim_engine::state::{Country, Currency, GameState, MacroData, Politics, TaxRates, TradePolicy, Treasury};
use std::collections::HashMap;
use std::path::Path;

/// Floating-point equality tolerance for golden-master parity comparisons.
const EPSILON: f64 = 1e-9;

/// Asserts that two `f64` values are within `epsilon` of each other.
macro_rules! assert_f64_eq {
    ($a:expr, $b:expr, $epsilon:expr) => {
        let a = $a;
        let b = $b;
        let epsilon = $epsilon;
        assert!(
            (a - b).abs() < epsilon,
            "assertion failed: |{} - {}| = {} >= epsilon {}",
            a,
            b,
            (a - b).abs(),
            epsilon
        );
    };
}

/// Path to the Python engine's `data/` directory, relative to this crate.
fn data_dir() -> std::path::PathBuf {
    Path::new(env!("CARGO_MANIFEST_DIR")).join("data")
}

/// Loads the first country from the real Python save as an owned value.
///
/// The caller must create the [`CountryTurnCtx`] in its own scope so the
/// mutable borrow outlives the context.
fn load_first_country() -> (String, Country) {
    let dir = data_dir();
    let game_state = load_game_state(&dir).expect("failed to load Python game state");
    game_state
        .countries
        .into_iter()
        .next()
        .expect("no countries in save")
}

/// Builds a hardcoded `turn_0` country used for the first parity test.
///
/// The sector map contains two sectors whose `employment` values sum to
/// 1000, so the Python `_calculate_gdp_shares_from_employment` will set the
/// GDP shares to 0.3 and 0.7 respectively.
fn hardcoded_turn_0_country() -> Country {
    use sim_engine::registries::enums::Sector;
    use sim_engine::state::treasury::SectorShare;

    Country::test_builder()
        .with_name("Iliria")
        .configure_treasury(|t| {
            t.gdp = 1000.0;
            t.population = 1000;
            t.nominal_budget = 10.0;
            t.liquid_reserves = 0.0;
            t.citizen_savings = 0.0;
            t.private_capital = 0.0;
            t.infrastructure_level = 1.0;
            t.energy_infrastructure = 1.0;
            t.stock_market.index = 100.0;
            t.stock_market.confidence = 50.0;
            t.stock_market.last_change = 0.0;
            t.allocations.industry = 0.14;
            t.allocations.education_propaganda = 0.14;
            t.allocations.healthcare = 0.14;
            t.allocations.infrastructure_transport = 0.14;
            t.allocations.social_programs = 0.15;
            t.allocations.agriculture_rural = 0.15;
            t.allocations.armed_forces = 0.14;
            t.black_ops_budget = 0.0;
            t.sectors.insert(
                Sector::Agriculture,
                SectorShare {
                    gdp_share: 0.0,
                    crisis_vulnerability: None,
                    active_method: None,
                    extra: {
                        let mut map = serde_json::Map::new();
                        map.insert("employment".to_string(), serde_json::json!(300));
                        map
                    },
                },
            );
            t.sectors.insert(
                Sector::HeavyIndustry,
                SectorShare {
                    gdp_share: 0.0,
                    crisis_vulnerability: None,
                    active_method: None,
                    extra: {
                        let mut map = serde_json::Map::new();
                        map.insert("employment".to_string(), serde_json::json!(700));
                        map
                    },
                },
            );
            t.science.innovation_points = 0.0;
            t.science.researching = None;
            t.science.discovered = Vec::new();
            t.science.base_innovativeness = 0.0;
            t.last_balance_log = String::new();
        })
        .configure_macro_indicators(|m| {
            m.inflation = 0.0;
            m.gini = 0.0;
            m.social_unrest = 0.0;
            m.wealth_bracket = sim_engine::registries::enums::WealthBracket::High;
            m.productivity = 1.0;
            m.currency = "ILI".to_string();
            m.energy_mix.coal = 0.0;
            m.energy_mix.natural_gas = 0.0;
            m.energy_mix.uranium = 0.0;
            m.energy_mix.renewables = 1.0;
            m.average_wage = 1.0;
            m.culture = "Iliria".to_string();
            m.cultural_group = String::new();
            m.religion = String::new();
        })
        .configure_tax_rates(|t| {
            t.income_tax.rate = 0.0;
            t.income_tax.structure = "linear".to_string();
            t.corporate_tax = 0.0;
            t.public_debt.current_debt = 0.0;
            t.public_debt.interest_rate = 0.0;
        })
        .build()
}

#[test]
fn gdp_share_parity_against_hardcoded_expected() {
    let reg = Registries::native_only();
    let mut country = hardcoded_turn_0_country();
    let mut ctx = CountryTurnCtx {
        country_name: country.name.clone(),
        turn: 0,
        year: 2020,
        registries: &reg,
        country: &mut country,
        buildings: Vec::new(),
        market_prices: std::collections::HashMap::new(),
    };

    update_gdp_shares_from_employment(&mut ctx);

    // Turn 1 expected values (computed by the Python `_calculate_gdp_shares_from_employment`).
    let sectors = &ctx.country.budget.sectors;
    let rolnictwo = &sectors[&sim_engine::registries::enums::Sector::Agriculture];
    let przemysl_ciezki = &sectors[&sim_engine::registries::enums::Sector::HeavyIndustry];

    assert_f64_eq!(rolnictwo.gdp_share, 0.3, EPSILON);
    assert_f64_eq!(przemysl_ciezki.gdp_share, 0.7, EPSILON);
}

#[test]
fn harness_loads_real_save_and_runs_turn_1() {
    let reg = Registries::native_only();
    let (name, mut country) = load_first_country();
    let mut ctx = CountryTurnCtx {
        country_name: name,
        turn: 0,
        year: 2020,
        registries: &reg,
        country: &mut country,
        buildings: Vec::new(),
        market_prices: std::collections::HashMap::new(),
    };
    let result = run_economic_turn(&mut ctx).expect("turn function should not error");

    // No golden-master snapshot exists yet for the full turn.
    assert_eq!(result, ParityResult::MissingExpected);
}

#[test]
fn harness_can_load_any_country_by_name() {
    let dir = data_dir();
    let mut country = load_country_data(&dir, "Anglia")
        .expect("expected Anglia to be present in the test save");

    let reg = Registries::native_only();
    let mut ctx = CountryTurnCtx {
        country_name: country.name.clone(),
        turn: 0,
        year: 2020,
        registries: &reg,
        country: &mut country,
        buildings: Vec::new(),
        market_prices: std::collections::HashMap::new(),
    };
    let result = run_economic_turn(&mut ctx).expect("turn function should not error");
    assert_eq!(result, ParityResult::MissingExpected);
}

#[test]
fn fractional_reserve_parity_test() {
    use sim_engine::registries::enums::Sector;
    use sim_engine::entities::{LegalForm, JointStockData};
    use sim_engine::state::banking::{BankBalanceSheet, BankType};
    use sim_engine::state::process_banking_turn;

    let balance_sheet = BankBalanceSheet {
        reserves_at_central_bank: 100_000.0,
        deposits: 1_000_000.0,
        tier_1_capital: 10_000_000.0,
        ..Default::default()
    };

    let mut bank_company = Company::new(
        "TEST-1".to_string(),
        "Test Bank".to_string(),
        Sector::Banking,
        LegalForm::JointStockCompany(JointStockData::default()),
        0.0,
        0.0,
        0,
    );
    bank_company.bank_type = Some(BankType::Commercial);
    bank_company.balance_sheet = Some(balance_sheet);

    // Borrower company: needs working capital (worker_capacity * 1000 - available_cash)
    let mut borrower = Company::new(
        "BORROW-1".to_string(),
        "Borrower Corp".to_string(),
        Sector::HeavyIndustry,
        LegalForm::JointStockCompany(JointStockData::default()),
        1_000_000.0, // fixed_capital = collateral for loan
        100_000.0,   // liquid_capital
        600,          // worker_capacity = 600 → needs 600,000 working capital
    );
    borrower.available_cash = 100_000.0; // Has 100k, needs 500k more (within per-loan cap)

    let mut companies = vec![bank_company, borrower];

    let mut country = Country::test_builder()
        .with_name("Testlandia")
        .configure_treasury(|t| {
            t.gdp = 1000.0;
            t.population = 1000;
            t.nominal_budget = 10.0;
            t.liquid_reserves = 0.0;
            t.citizen_savings = 0.0;
            t.private_capital = 0.0;
            t.infrastructure_level = 1.0;
            t.energy_infrastructure = 1.0;
            t.stock_market.index = 100.0;
            t.stock_market.confidence = 50.0;
            t.stock_market.last_change = 0.0;
            t.allocations.industry = 0.14;
            t.allocations.education_propaganda = 0.14;
            t.allocations.healthcare = 0.14;
            t.allocations.infrastructure_transport = 0.14;
            t.allocations.social_programs = 0.15;
            t.allocations.agriculture_rural = 0.15;
            t.allocations.armed_forces = 0.14;
            t.black_ops_budget = 0.0;
            t.science.innovation_points = 0.0;
            t.science.researching = None;
            t.science.discovered = Vec::new();
            t.science.base_innovativeness = 0.0;
            t.last_balance_log = String::new();
        })
        .configure_macro_indicators(|m| {
            m.inflation = 0.0;
            m.gini = 0.0;
            m.social_unrest = 0.0;
            m.wealth_bracket = sim_engine::registries::enums::WealthBracket::High;
            m.productivity = 1.0;
            m.currency = "TST".to_string();
            m.energy_mix.coal = 0.0;
            m.energy_mix.natural_gas = 0.0;
            m.energy_mix.uranium = 0.0;
            m.energy_mix.renewables = 1.0;
            m.average_wage = 1.0;
            m.culture = "Testlandian".to_string();
            m.cultural_group = String::new();
            m.religion = String::new();
        })
        .configure_tax_rates(|t| {
            t.income_tax.rate = 0.0;
            t.income_tax.structure = "linear".to_string();
            t.corporate_tax = 0.0;
            t.public_debt.current_debt = 0.0;
            t.public_debt.interest_rate = 0.0;
        })
        .build();

    let _result = process_banking_turn(&mut country, &mut companies, 0);

    let bs = companies[0].balance_sheet.as_ref().expect("bank should have balance sheet");
    // Borrower needs 500,000 (600 * 1000 - 100,000), within the per-loan cap of 500,000.
    let total_loans: f64 = bs.loans_issued.iter().map(|l| l.outstanding_balance).sum();
    assert_f64_eq!(total_loans, 500_000.0, EPSILON);
}

#[test]
