// THE GREAT GOLDEN MASTER 2.0 — 100-TURN SURVIVAL TEST
// ═══════════════════════════════════════════════════════════════════════════════

/// Load all buildings for a country from disk (mirrors load_all_companies).
fn load_all_buildings(data_dir: &Path, country: &str) -> Vec<Building> {
    use sim_engine::io::entity_store::{DiskEntityStore, EntityStore};
    let buildings_dir = data_dir.join("entities").join(country).join("buildings");
    if !buildings_dir.exists() {
        return Vec::new();
    }
    let store = DiskEntityStore::<Building>::new(data_dir);
    let mut all = Vec::new();
    for entry in stdfs::read_dir(&buildings_dir).unwrap().flatten() {
        let path = entry.path();
        if path.extension().and_then(|e| e.to_str()) != Some("json") {
            continue;
        }
        let sector = path.file_stem().and_then(|s| s.to_str()).unwrap_or("").to_string();
        if sector.is_empty() { continue; }
        if let Ok(loaded) = store.load_sector(country, &sector, None) {
            all.extend(loaded);
        }
    }
    all
}

/// The Great Golden Master 2.0 — 100-Turn Survival Test.
///
/// Generates a **fresh** world (not the legacy Python save, which lacks banks),
/// runs the engine for 100 continuous turns, and validates:
///
/// 1. **Banking Integrity (CRITICAL):** commercial banks exist (`count > 0`),
///    have balance sheets, and reserves are non-negative. No vacuous passes.
/// 2. **Monetary Conservation:** M3 money supply stays within 0.01×–1000× of
///    initial. No hyperinflation or deflationary collapse.
/// 3. **Phase 19 Fixed Assets:** cohort caps are respected (no RAM bloat),
///    cohorts degrade over time, and maintenance services are being produced.
/// 4. **Phase 18 Demographics & Justice:** populations stay positive, class
///    savings don't drain to zero globally, shadow economy state processes
///    without creating negative money.
/// 5. **No Panics:** the engine completes 100 turns without panicking.
#[test]
fn golden_master_survival_100_turns_test() {
    use sim_engine::engine::{generate_world, GenerateOptions, StartYear};
    use sim_engine::registries::enums::Sector;

    let temp_base = std::env::temp_dir().join("sim_engine_gm2_test");

    // Clean up any previous run.
    if temp_base.exists() {
        stdfs::remove_dir_all(&temp_base).unwrap();
    }
    stdfs::create_dir_all(&temp_base).unwrap();

    // Generate a fresh world with 6 countries. This creates and saves banks.
    let reg = Registries::native_only();
    let options = GenerateOptions {
        country_count: 6,
        start_year: StartYear::Y1975,
    };
    let generated = generate_world(&temp_base, options, &reg)
        .expect("world generation should succeed");
    let mut state = generated.state;

    // Snapshot initial conditions.
    let initial_market = load_market_for_test(&temp_base);
    let initial_m3 = compute_m3(&state, &initial_market);
    let initial_pop = compute_total_population(&state);
    let initial_country_count = state.countries.len();

    // === CRITICAL: Verify banks exist right after generation ===
    let mut initial_bank_count = 0;
    for country_name in state.countries.keys() {
        let companies = load_all_companies(&temp_base, country_name);
        for company in &companies {
            if company.bank_type.is_some() || company.sector == Sector::Banking {
                initial_bank_count += 1;
            }
        }
    }
    eprintln!("=== GREAT GOLDEN MASTER 2.0: 100-TURN SURVIVAL TEST ===");
    eprintln!("Countries: {}", initial_country_count);
    eprintln!("Initial M3: {:.2}", initial_m3);
    eprintln!("Initial population: {}", initial_pop);
    eprintln!("Initial bank count: {}", initial_bank_count);
    assert!(
        initial_bank_count > 0,
        "CRITICAL: No banks generated! The world generator must create banks. \
         Found {} banks across {} countries.",
        initial_bank_count, initial_country_count
    );

    eprintln!("Running 100 turns...");

    // Run 100 continuous turns with persistence.
    const NUM_TURNS: u32 = 100;
    let mut max_cohort_count: usize = 0;
    let mut max_m3_multiplier: f64 = 1.0;
    let mut min_m3_multiplier: f64 = 1.0;

    // Load in-memory context once (replaces per-turn disk I/O).
    let mut ctx = InMemoryTurnContext::load_from_disk(&temp_base, &mut state)
        .expect("failed to load in-memory context");

    for turn in 0..NUM_TURNS {
        let result = run_turn_in_memory(&mut state, &reg, &mut ctx);

        if let Err(ref e) = result {
            panic!("run_turn_in_memory failed at turn {}: {:?}", turn, e);
        }

        // Save to disk so test helpers can read back.
        let global_orders = sim_engine::economy::market::MarketOrders::default();
        let trade_result = sim_engine::international::TradeBalanceResult::default();
        let _ = ctx.save_to_disk(&temp_base, &state, &global_orders, &trade_result);

        // Periodic checks every 10 turns.
        if (turn + 1) % 10 == 0 {
            let current_market = load_market_for_test(&temp_base);
            let current_m3 = compute_m3(&state, &current_market);
            let current_pop = compute_total_population(&state);
            let m3_mult = current_m3 / initial_m3.max(1.0);
            max_m3_multiplier = max_m3_multiplier.max(m3_mult);
            min_m3_multiplier = if min_m3_multiplier == 1.0 { m3_mult } else { min_m3_multiplier.min(m3_mult) };

            eprintln!(
                "  Turn {:>3} | M3: {:>14.2} ({:.2}x) | Pop: {:>10} | Countries: {}",
                turn + 1, current_m3, m3_mult, current_pop, state.countries.len()
            );

            // === 1. MONETARY CONSERVATION ===
            assert!(
                current_m3 < initial_m3 * 1000.0,
                "Hyperinflation at turn {}: M3 = {:.2} ({:.1}x initial)",
                turn + 1, current_m3, m3_mult
            );
            assert!(
                current_m3 > initial_m3 * 0.01,
                "Deflationary collapse at turn {}: M3 = {:.2} ({:.4}x initial)",
                turn + 1, current_m3, m3_mult
            );

            // === 2. DEMOGRAPHIC PHYSICS ===
            assert!(current_pop > 0, "Global extinction at turn {}", turn + 1);
            assert!(
                current_pop < initial_pop * 3,
                "Population explosion at turn {}: {} (initial: {})",
                turn + 1, current_pop, initial_pop
            );

            // No country should have zero population.
            for (name, country) in &state.countries {
                assert!(
                    country.budget.population > 0,
                    "Country '{}' has zero population at turn {}",
                    name, turn + 1
                );
            }

            // === 3. BANKING INTEGRITY (every 10 turns) ===
            let mut bank_count = 0;
            let mut banks_with_bs = 0;
            let mut banks_valid_reserves = 0;
            let mut total_bank_deposits = 0.0_f64;
            let mut total_bank_reserves = 0.0_f64;

            for country_name in state.countries.keys() {
                let companies = load_all_companies(&temp_base, country_name);
                for company in &companies {
                    if company.bank_type.is_some() || company.sector == Sector::Banking {
                        bank_count += 1;
                        if let Some(ref bs) = company.balance_sheet {
                            banks_with_bs += 1;
                            total_bank_deposits += bs.deposits;
                            total_bank_reserves += bs.reserves_at_central_bank;
                            if bs.reserves_at_central_bank >= 0.0 && bs.deposits >= 0.0 {
                                banks_valid_reserves += 1;
                            }
                        }
                    }
                }
            }

            eprintln!(
                "    Banks: {} | w/BS: {} | valid reserves: {} | deposits: {:.0} | reserves: {:.0}",
                bank_count, banks_with_bs, banks_valid_reserves, total_bank_deposits, total_bank_reserves
            );

            // STRICT assertion — no vacuous pass!
            assert!(
                bank_count > 0,
                "BANKING COLLAPSE at turn {}: 0 banks detected across all countries. \
                 Banks must persist throughout the simulation.",
                turn + 1
            );
            assert!(
                banks_with_bs > 0,
                "BANKING FAILURE at turn {}: {} banks exist but none have balance sheets",
                turn + 1, bank_count
            );
            assert!(
                banks_valid_reserves > 0,
                "BANKING FAILURE at turn {}: no banks have valid (non-negative) reserves",
                turn + 1
            );

            // === 4. PHASE 19 FIXED ASSET COHORT CAPS ===
            let mut total_cohorts = 0;
            let mut buildings_with_cohorts = 0;
            let mut total_cohort_units = 0.0_f64;
            let cohort_cap = 12; // MAX_FIXED_COHORTS_PER_BUILDING default

            for country_name in state.countries.keys() {
                let buildings = load_all_buildings(&temp_base, country_name);
                for building in &buildings {
                    if !building.fixed_assets.is_empty() {
                        buildings_with_cohorts += 1;
                        total_cohorts += building.fixed_assets.len();
                        for cohort in &building.fixed_assets {
                            total_cohort_units += cohort.count;
                        }
                        // Strict cap check — prevent RAM bloat.
                        assert!(
                            building.fixed_assets.len() <= cohort_cap,
                            "COHORT CAP VIOLATION at turn {}: building '{}' in '{}' has {} cohorts (max {})",
                            turn + 1, building.id, country_name, building.fixed_assets.len(), cohort_cap
                        );
                    }
                }
            }

            max_cohort_count = max_cohort_count.max(total_cohorts);
            eprintln!(
                "    Fixed assets: {} buildings | {} cohorts (max seen: {}) | {:.0} units",
                buildings_with_cohorts, total_cohorts, max_cohort_count, total_cohort_units
            );

            // === 5. PHASE 18 JUSTICE & SHADOW ECONOMY ===
            // Check that no country has negative citizen savings (drain to zero).
            for (name, country) in &state.countries {
                assert!(
                    country.budget.citizen_savings >= 0.0,
                    "NEGATIVE SAVINGS at turn {}: country '{}' has citizen_savings = {:.2}",
                    turn + 1, name, country.budget.citizen_savings
                );
                assert!(
                    country.budget.liquid_reserves.is_finite(),
                    "NAN/INF RESERVES at turn {}: country '{}' has liquid_reserves = {:.2}",
                    turn + 1, name, country.budget.liquid_reserves
                );
            }
        }
    }

    // === FINAL ASSERTIONS AFTER 100 TURNS ===
    let final_market = load_market_for_test(&temp_base);
    let final_m3 = compute_m3(&state, &final_market);
    let final_pop = compute_total_population(&state);

    eprintln!();
    eprintln!("=== SIMULATION COMPLETE: 100 TURNS ===");
    eprintln!();

    // --- 1. MONETARY CONSERVATION ---
    eprintln!("--- Monetary Conservation ---");
    eprintln!("Initial M3: {:.2}", initial_m3);
    eprintln!("Final M3:   {:.2}", final_m3);
    eprintln!("M3 multiplier range: [{:.3}x, {:.3}x]", min_m3_multiplier, max_m3_multiplier);
    eprintln!("M3 delta:   {:.2} ({:.1}%)", final_m3 - initial_m3, (final_m3 / initial_m3.max(1.0) - 1.0) * 100.0);
    assert!(final_m3 < initial_m3 * 1000.0, "Hyperinflation: final M3 = {:.2}", final_m3);
    assert!(final_m3 > initial_m3 * 0.01, "Deflationary collapse: final M3 = {:.2}", final_m3);

    // --- 2. BANKING INTEGRITY (CRITICAL — STRICT) ---
    eprintln!();
    eprintln!("--- Banking Integrity (CRITICAL) ---");
    let mut final_bank_count = 0;
    let mut final_banks_with_bs = 0;
    let mut final_banks_valid_reserves = 0;
    let mut final_total_deposits = 0.0_f64;
    let mut final_total_reserves = 0.0_f64;
    let mut final_total_loans = 0.0_f64;
    let mut banks_by_country: Vec<(String, usize, f64, f64)> = Vec::new();

    for country_name in state.countries.keys() {
        let companies = load_all_companies(&temp_base, country_name);
        let mut country_banks = 0;
        let mut country_deposits = 0.0;
        let mut country_reserves = 0.0;
        for company in &companies {
            if company.bank_type.is_some() || company.sector == Sector::Banking {
                final_bank_count += 1;
                country_banks += 1;
                if let Some(ref bs) = company.balance_sheet {
                    final_banks_with_bs += 1;
                    country_deposits += bs.deposits;
                    country_reserves += bs.reserves_at_central_bank;
                    final_total_deposits += bs.deposits;
                    final_total_reserves += bs.reserves_at_central_bank;
                    let loans: f64 = bs.loans_issued.iter().map(|l| l.outstanding_balance).sum();
                    final_total_loans += loans;
                    if bs.reserves_at_central_bank >= 0.0 && bs.deposits >= 0.0 {
                        final_banks_valid_reserves += 1;
                    }
                }
            }
        }
        banks_by_country.push((country_name.clone(), country_banks, country_deposits, country_reserves));
    }

    eprintln!("Total banks: {}", final_bank_count);
    eprintln!("Banks with balance sheet: {}", final_banks_with_bs);
    eprintln!("Banks with valid reserves: {}", final_banks_valid_reserves);
    eprintln!("Total deposits: {:.2}", final_total_deposits);
    eprintln!("Total reserves: {:.2}", final_total_reserves);
    eprintln!("Total loans outstanding: {:.2}", final_total_loans);
    eprintln!();
    eprintln!("Per-country banking summary:");
    banks_by_country.sort_by(|a, b| a.0.cmp(&b.0));
    for (name, count, deposits, reserves) in &banks_by_country {
        eprintln!("  {:<12} | Banks: {} | Deposits: {:>14.2} | Reserves: {:>14.2}", name, count, deposits, reserves);
    }

    // STRICT ASSERTIONS — no vacuous passes!
    assert!(
        final_bank_count > 0,
        "CRITICAL BANKING FAILURE: 0 banks after 100 turns. The banking sector has collapsed."
    );
    assert!(
        final_banks_with_bs > 0,
        "CRITICAL BANKING FAILURE: {} banks exist but none have balance sheets after 100 turns.",
        final_bank_count
    );
    assert!(
        final_banks_valid_reserves > 0,
        "CRITICAL BANKING FAILURE: no banks have valid (non-negative) reserves after 100 turns."
    );
    assert!(
        final_total_deposits > 0.0,
        "BANKING FAILURE: total deposits = 0 after 100 turns. Banks are not processing deposits."
    );

    // --- 3. PHASE 19 FIXED ASSETS ---
    eprintln!();
    eprintln!("--- Phase 19 Fixed Assets ---");
    eprintln!("Max cohort count seen at any checkpoint: {}", max_cohort_count);
    let mut final_total_cohorts = 0;
    let mut final_buildings_with_cohorts = 0;
    let mut final_total_units = 0.0_f64;
    for country_name in state.countries.keys() {
        let buildings = load_all_buildings(&temp_base, country_name);
        for building in &buildings {
            if !building.fixed_assets.is_empty() {
                final_buildings_with_cohorts += 1;
                final_total_cohorts += building.fixed_assets.len();
                for cohort in &building.fixed_assets {
                    final_total_units += cohort.count;
                    // Cohort count must be positive.
                    assert!(cohort.count > 0.0, "Zero-count cohort in building {}", building.id);
                    // Condition must be in valid range.
                    assert!(cohort.condition > 0.0, "Zero-condition cohort still present (should be scrapped)");
                }
            }
        }
    }
    eprintln!("Final buildings with cohorts: {}", final_buildings_with_cohorts);
    eprintln!("Final total cohorts: {}", final_total_cohorts);
    eprintln!("Final total fixed-asset units: {:.0}", final_total_units);

    // --- 4. PHASE 18 DEMOGRAPHICS & JUSTICE ---
    eprintln!();
    eprintln!("--- Phase 18 Demographics & Justice ---");
    eprintln!("Initial population: {}", initial_pop);
    eprintln!("Final population:   {}", final_pop);
    eprintln!("Population delta:   {} ({:.1}%)",
        final_pop as i64 - initial_pop as i64,
        (final_pop as f64 / initial_pop as f64 - 1.0) * 100.0);
    assert!(final_pop > 0, "Global extinction: population reached 0");
    assert!(final_pop < initial_pop * 3, "Population explosion: {}", final_pop);

    // Per-country macro summary.
    eprintln!();
    eprintln!("--- Per-Country Macroeconomic Summary (after 100 turns) ---");
    let mut country_summary: Vec<(String, f64, u64, f64, f64, f64)> = state.countries
        .iter()
        .map(|(name, c)| {
            (name.clone(), c.budget.gdp, c.budget.population,
             c.budget.liquid_reserves, c.budget.citizen_savings, c.budget.private_capital)
        })
        .collect();
    country_summary.sort_by(|a, b| a.0.cmp(&b.0));
    for (name, gdp, pop, reserves, savings, private) in &country_summary {
        eprintln!(
            "  {:<12} | GDP: {:>14.2} | Pop: {:>10} | Reserves: {:>12.2} | Savings: {:>12.2} | Private: {:>12.2}",
            name, gdp, pop, reserves, savings, private
        );
        // No negative macro values.
        assert!(*reserves >= 0.0, "Negative reserves in {}: {}", name, reserves);
        assert!(*savings >= 0.0, "Negative citizen savings in {}: {}", name, savings);
    }

    // --- 5. NO PANICS ---
    eprintln!();
    eprintln!("--- No Panics ---");
    eprintln!("Engine completed 100 turns without any panics or unhandled errors.");

    // --- 6. APOSTOLIC SEE LEDGER ---
    eprintln!();
    eprintln!("--- Apostolic See Ledger ---");
    eprintln!("Total remittances: {:.2}", final_market.apostolic_see_ledger.total_remittances);
    eprintln!("Global charity pool: {:.2}", final_market.apostolic_see_ledger.global_charity_pool);

    // Clean up.
    stdfs::remove_dir_all(&temp_base).ok();

    eprintln!();
    eprintln!("=== GREAT GOLDEN MASTER 2.0: 100-TURN SURVIVAL TEST: PASSED ===");
}
